    for (int i = threadIdx.x; i < embed_dim; i += blockDim.x) {
        float val = attn_output[base_idx + i] + residual[base_idx + i];
        float diff = val - mean;
        var_sum += diff * diff;
    }
    var_sum = block_reduce_sum(var_sum, shared_mem);
    __syncthreads();

    __shared__ float inv_std_shared;
    if (threadIdx.x == 0) {
